const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'G' },
      { kind: 'text', payload: 'N' },
      { kind: 'text', payload: 'f' },
      { kind: 'text', payload: '30°' }
    ];
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 720;
    var H = (input.viewport && input.viewport.heightDu) || 480;
    var tan30 = Math.tan(Math.PI / 6);
    var groundY = H * 0.84;
    var A = { x: W * 0.16, y: groundY };
    var maxDxW = W * 0.60;
    var maxDxH = (groundY - H * 0.16) / tan30;
    var dx = Math.max(W * 0.30, Math.min(maxDxW, maxDxH));
    var B = { x: A.x + dx, y: groundY - dx * tan30 };
    var Cbase = { x: B.x, y: groundY };
    var u = { x: Math.cos(Math.PI / 6), y: -Math.sin(Math.PI / 6) };
    var n = { x: -Math.sin(Math.PI / 6), y: -Math.cos(Math.PI / 6) };
    var t = 0.52;
    var S = { x: A.x + (B.x - A.x) * t, y: A.y + (B.y - A.y) * t };
    var Lb = Math.min(W * 0.12, 90);
    var Hb = Math.min(H * 0.07, 32);
    var Cc = { x: S.x + n.x * (Hb / 2), y: S.y + n.y * (Hb / 2) };
    function add(p, q, k) { return { x: p.x + q.x * k, y: p.y + q.y * k }; }
    var c1 = add(add(Cc, u, Lb / 2), n, Hb / 2);
    var c2 = add(add(Cc, u, -Lb / 2), n, Hb / 2);
    var c3 = add(add(Cc, u, -Lb / 2), n, -Hb / 2);
    var c4 = add(add(Cc, u, Lb / 2), n, -Hb / 2);
    function poly(points, close) {
      var cmds = [];
      for (var i = 0; i < points.length; i++) {
        cmds.push((i === 0 ? 'M' : 'L') + ' ' + points[i].x.toFixed(2) + ' ' + points[i].y.toFixed(2));
      }
      if (close) cmds.push('Z');
      return cmds;
    }
    var ground = poly([{ x: W * 0.06, y: groundY }, { x: W * 0.94, y: groundY }], false);
    var wedge = poly([A, B, Cbase], true);
    var block = poly([c1, c2, c3, c4], true);
    var Lg = H * 0.20;
    var Ln = H * 0.20;
    var Lf = H * 0.18;
    var gStart = { x: Cc.x, y: Cc.y };
    var gTip = { x: Cc.x, y: Cc.y + Lg };
    var nStart = { x: Cc.x, y: Cc.y };
    var nTip = { x: Cc.x + n.x * Ln, y: Cc.y + n.y * Ln };
    var fStart = { x: Cc.x, y: Cc.y };
    var fTip = { x: Cc.x + u.x * Lf, y: Cc.y + u.y * Lf };
    var gArrow = visualSdk.arrow(gStart.x, gStart.y, gTip.x, gTip.y, { headLength: 12, headWidth: 8 });
    var nArrow = visualSdk.arrow(nStart.x, nStart.y, nTip.x, nTip.y, { headLength: 12, headWidth: 8 });
    var fArrow = visualSdk.arrow(fStart.x, fStart.y, fTip.x, fTip.y, { headLength: 12, headWidth: 8 });
    var arcR = Math.min(W * 0.10, 70);
    var angleArc = visualSdk.arc(A.x, A.y, arcR, 0, -Math.PI / 6);
    var midAng = -Math.PI / 12;
    var angLabel = { x: A.x + (arcR + 28) * Math.cos(midAng), y: A.y + (arcR + 28) * Math.sin(midAng) };
    var gLabel = { x: gTip.x, y: gTip.y + 28 };
    var nLabel = { x: nTip.x - 12, y: nTip.y - 8 };
    var fLabel = { x: fTip.x + 12, y: fTip.y - 8 };
    var fsForce = 22;
    var fsAngle = 18;
    return {
      schemaVersion: 1,
      sceneId: 'force-diagram-30deg',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'ground', commands: ground },
        { id: 'wedge', commands: wedge },
        { id: 'block', commands: block },
        { id: 'gArrow', commands: gArrow },
        { id: 'nArrow', commands: nArrow },
        { id: 'fArrow', commands: fArrow },
        { id: 'angleArc', commands: angleArc }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'ground', stroke: '#8a96a8', strokeWidth: 2, fill: 'none' },
          { type: 'path', pathId: 'wedge', fill: '#e9eef6', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'block', fill: '#ffd166', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'gArrow', stroke: '#c0392b', strokeWidth: 3, fill: 'none' },
          { type: 'path', pathId: 'nArrow', stroke: '#1f6feb', strokeWidth: 3, fill: 'none' },
          { type: 'path', pathId: 'fArrow', stroke: '#2e8b57', strokeWidth: 3, fill: 'none' },
          { type: 'path', pathId: 'angleArc', stroke: '#26354a', strokeWidth: 1.5, fill: 'none' },
          { type: 'label', x: gLabel.x, y: gLabel.y, text: 'G', fontSize: fsForce, fill: '#c0392b', textAnchor: 'middle', fontStyle: 'italic', fontWeight: 600 },
          { type: 'label', x: nLabel.x, y: nLabel.y, text: 'N', fontSize: fsForce, fill: '#1f6feb', textAnchor: 'end', fontStyle: 'italic', fontWeight: 600 },
          { type: 'label', x: fLabel.x, y: fLabel.y, text: 'f', fontSize: fsForce, fill: '#2e8b57', textAnchor: 'start', fontStyle: 'italic', fontWeight: 600 },
          { type: 'label', x: angLabel.x, y: angLabel.y, text: '30°', fontSize: fsAngle, fill: '#26354a', textAnchor: 'middle' }
        ]
      }
    };
  }
};
